<script setup lang="ts">
import { ArrowLeft, Play, Pause, RotateCcw, Plus, Minus, Layers, LoaderCircle } from 'lucide-vue-next'
import { EARTH_RADIUS, earthLayers, earthSources } from '~/data/earth/interior'
import type { EarthLayerId } from '~/data/earth/interior'
import { advanceJourney, clampDepth, layerAtDepth, pressureAtDepth, temperatureAtDepth } from '~/utils/earth/interior'
import type { CountryFeature } from '~/utils/globe'
import type { EarthScene } from '~/utils/earth/scene.client'
const props=defineProps<{surfaceFeatures?:CountryFeature[]}>()
const emit=defineEmits<{back:[]}>()
const host=ref<HTMLElement|null>(null),loading=ref(true),error=ref(false)
const opening=ref(1)
const depth=ref(0),travelling=ref(false),reduced=ref(false)
const layer=computed(()=>layerAtDepth(depth.value)),temperature=computed(()=>temperatureAtDepth(depth.value)),pressure=computed(()=>pressureAtDepth(depth.value))
const number=new Intl.NumberFormat('hy-AM',{maximumFractionDigits:1})
let scene:EarthScene|undefined,disposed=false,loadPending=false,frame=0,last=0
let preference:MediaQueryList|undefined
function chooseDepth(value:number){travelling.value=false;depth.value=clampDepth(value)}
function chooseLayer(id:EarthLayerId){const target=earthLayers.find(item=>item.id===id)!;chooseDepth(target.top===0?0:target.top+Math.min(50,(target.bottom-target.top)/2))}
watch(() => props.surfaceFeatures, features => scene?.setSurface(features || []))
watch(depth,value=>scene?.setDepth(value))
watch(opening,value=>scene?.setOpening(value))
watch(()=>layer.value.id,id=>scene?.setLayer(id))
function stop(){cancelAnimationFrame(frame);frame=0;last=0}
function animate(time:number){frame=0;if(!travelling.value||disposed||document.hidden)return;if(last&&time-last<1000/30){frame=requestAnimationFrame(animate);return}const elapsed=last?(time-last)/1000:0;last=time;depth.value=advanceJourney(depth.value,elapsed);if(depth.value>=EARTH_RADIUS){travelling.value=false;return}frame=requestAnimationFrame(animate)}
watch(travelling,value=>{stop();if(value&&!document.hidden)frame=requestAnimationFrame(animate)})
function toggleJourney(){if(travelling.value){travelling.value=false;return}if(depth.value>=EARTH_RADIUS)depth.value=0;travelling.value=true}
function visibility(){if(document.hidden)travelling.value=false}
function motionChange(event:MediaQueryListEvent){reduced.value=event.matches;scene?.setReducedMotion(event.matches);if(event.matches)travelling.value=false}
async function load(){
  if(loadPending||disposed||!host.value)return
  loadPending=true;loading.value=true;error.value=false
  try{const {createEarthScene}=await import('~/utils/earth/scene.client');if(disposed||!host.value)return;scene?.dispose();scene=createEarthScene(host.value,chooseLayer,()=>{error.value=true;travelling.value=false},reduced.value);scene.setSurface(props.surfaceFeatures || []);scene.setOpening(opening.value);scene.setDepth(depth.value);scene.setLayer(layer.value.id)}catch{error.value=true}finally{loadPending=false;if(!disposed)loading.value=false}
}
function keyboard(event:KeyboardEvent){if(error.value||loading.value)return;const actions:Record<string,()=>void>={ArrowLeft:()=>scene?.rotate(-.12,0),ArrowRight:()=>scene?.rotate(.12,0),ArrowUp:()=>scene?.rotate(0,-.12),ArrowDown:()=>scene?.rotate(0,.12),'+':()=>scene?.zoom(.85),'=':()=>scene?.zoom(.85),'-':()=>scene?.zoom(1.18),Home:()=>scene?.reset()};if(actions[event.key]){event.preventDefault();actions[event.key]!()}}
function leave(){travelling.value=false;emit('back')}
onMounted(()=>{preference=window.matchMedia('(prefers-reduced-motion: reduce)');reduced.value=preference.matches;preference.addEventListener('change',motionChange);document.addEventListener('visibilitychange',visibility);void load()})
onBeforeUnmount(()=>{disposed=true;travelling.value=false;stop();preference?.removeEventListener('change',motionChange);document.removeEventListener('visibilitychange',visibility);scene?.dispose()})
</script>
<template>
  <section class="earth-interior" aria-label="Երկրի խորքերը">
    <header class="earth-heading"><div><p class="earth-eyebrow">COGNITIO · ՃԱՆԱՊԱՐՀՈՐԴՈՒԹՅՈՒՆ ԴԵՊԻ ԿԵՆՏՐՈՆ</p><h2>Երկրի խորքերը</h2><p>Մակերևույթից մինչև կենտրոն՝ 6371 կմ։ Բացիր շերտերը և իմացիր՝ ինչ կա մեր ոտքերի տակ։</p></div><button type="button" class="btn-secondary earth-back" @click="leave"><ArrowLeft :size="17"/>Վերադառնալ գլոբուսին</button></header>
    <div class="earth-workspace">
      <div class="panel earth-stage">
        <div class="earth-stage-title"><span><Layers :size="16"/>Երկրի 3D կտրվածք</span><span>Շերտերի շառավիղները՝ համամասնորեն</span></div>
        <div ref="host" class="earth-canvas" tabindex="0" role="group" aria-label="Երկրի պտտվող եռաչափ կտրվածք։ Շերտը կարող ես ընտրել նաև անվան կոճակով։" :aria-busy="loading" aria-describedby="earth-controls-help" @keydown="keyboard"/>
        <div v-if="loading||error" class="earth-message" role="status"><LoaderCircle v-if="loading" :size="30" class="earth-spinner"/><p>{{ loading?'Պատրաստում ենք Երկրի կտրվածքը…':'3D դիտարկիչը չհաջողվեց գործարկել։ Շերտերի տվյալները, խորության սահիչն ու գրաֆիկները շարունակում են աշխատել։' }}</p><button v-if="error" type="button" class="btn-secondary" @click="load">Կրկին փորձել</button></div>
        <div class="earth-cut-control"><label for="earth-opening">Բացիր Երկրի կտրվածքը <span>{{ Math.round(opening * 100) }}%</span></label><input id="earth-opening" v-model.number="opening" type="range" min="0" max="1" step="0.01" :disabled="loading||error"><div><span>Ամբողջական գունդ</span><span>Բաց շերտեր</span></div></div>
        <div class="earth-stage-legend" aria-label="Շերտերի արագ ընտրություն"><button v-for="item in earthLayers" :key="item.id" type="button" :aria-pressed="item.id===layer.id" :style="{'--layer-color':item.color}" @click="chooseLayer(item.id)"><i aria-hidden="true"/>{{ item.name }}</button></div>
        <div class="earth-view-controls"><button type="button" :disabled="loading||error" aria-label="Մեծացնել" @click="scene?.zoom(.85)"><Plus :size="18"/></button><button type="button" :disabled="loading||error" aria-label="Փոքրացնել" @click="scene?.zoom(1.18)"><Minus :size="18"/></button><button type="button" :disabled="loading||error" @click="scene?.reset()"><RotateCcw :size="16"/>Սկզբնական դիրք</button></div>
        <p id="earth-controls-help" class="earth-help">Քաշիր՝ պտտելու, անիվով կամ երկու մատով՝ մեծացնելու համար։ Հպվիր շերտին՝ ընտրելու համար։ Ստեղնաշար՝ սլաքներ, +/−, Home։ Լուսավոր կետը ընտրված խորությունն է․ այն պայմանական նշիչ է։</p>
      </div>
      <aside class="panel earth-information" aria-label="Ընտրված խորության տվյալները">
        <div class="earth-depth-value"><span>Խորությունը մակերևույթից</span><strong>{{ number.format(depth) }} <small>կմ</small></strong></div>
        <label for="earth-depth" class="earth-depth-label">Ճանապարհորդիր դեպի կենտրոն<input id="earth-depth" :value="depth" type="range" min="0" :max="EARTH_RADIUS" step="1" :aria-valuetext="`${Math.round(depth)} կմ․ ${layer.name}`" @input="chooseDepth(Number(($event.target as HTMLInputElement).value))"></label>
        <div class="earth-scale"><span>Մակերևույթ · 0</span><span>Կենտրոն · 6371 կմ</span></div>
        <div class="earth-journey-controls"><button type="button" :aria-pressed="travelling" @click="toggleJourney"><Pause v-if="travelling" :size="17"/><Play v-else :size="17"/>{{ travelling?'Կանգնեցնել':depth>=EARTH_RADIUS?'Նորից ճանապարհորդել':depth>0?'Շարունակել':'Սկսել ճանապարհորդությունը' }}</button><button type="button" aria-label="Վերադառնալ մակերևույթ" @click="chooseDepth(0)"><RotateCcw :size="17"/></button></div>
        <p v-if="reduced" class="earth-note">Նվազեցված շարժումը միացված է․ կտրվածքը բացվում է անմիջապես։ Ավտոմատ ճանապարհորդությունը սկսվում է միայն քո հրահանգով։</p>
        <div class="earth-layer-buttons" role="group" aria-label="Երկրի շերտերը"><button v-for="item in earthLayers" :key="item.id" type="button" :aria-pressed="item.id===layer.id" :style="{'--layer-color':item.color}" @click="chooseLayer(item.id)"><i aria-hidden="true"/>{{ item.name }}</button></div>
        <article class="earth-layer-detail" :style="{'--layer-color':layer.color}"><h3>{{ layer.name }} <span>{{ layer.state }}</span></h3><dl><div><dt>Խորության սահմաններ</dt><dd>{{ number.format(layer.top) }}–{{ number.format(layer.bottom) }} կմ</dd></div><div><dt>Հաստությունը մոդելում</dt><dd>{{ number.format(layer.bottom-layer.top) }} կմ</dd></div><div><dt>Այս խորության ջերմաստիճանը</dt><dd>≈ {{ Math.round(temperature.low) }}{{ temperature.low === temperature.high ? '' : `–${Math.round(temperature.high)}` }} °C</dd></div><div><dt>Այս խորության ճնշումը</dt><dd>≈ {{ number.format(pressure) }} ԳՊա</dd></div></dl><h4>Ինչի՞ց է կազմված</h4><p>{{ layer.composition }}</p><h4>Ի՞նչ է այստեղ տեղի ունենում</h4><p>{{ layer.explanation }}</p><p class="earth-note">{{ layer.temperature }}</p></article>
      </aside>
    </div>
    <section class="earth-stops" aria-label="Ճանապարհորդության կանգառները"><button v-for="(item,index) in earthLayers" :key="item.id" type="button" :aria-pressed="item.id===layer.id" :style="{'--layer-color':item.color}" @click="chooseLayer(item.id)"><span class="earth-stop-number">0{{ index+1 }}</span><span><strong>{{ item.name }}</strong><small>{{ number.format(item.top) }}–{{ number.format(item.bottom) }} կմ · {{ item.state }}</small></span><span aria-hidden="true">↗</span></button></section>
    <EarthInteriorCharts :depth="depth" @select="chooseDepth"/>
    <div class="panel earth-method"><h3>Ինչպե՞ս գիտենք՝ ինչ կա Երկրի ներսում</h3><p>Սեյսմիկ ալիքների տարածումը, Երկրի զանգվածը և լաբորատոր փորձերը օգնում են գնահատել ներքին կառուցվածքը։ Սա PREM-ի գնդային միջին շերտերով ուսուցողական 3D մոդել է, ոչ իրական հորատում կամ տեղային երկրաբանական քարտեզ։ Գույները, ապարների մանրամասներն ու մետաղական մակերեսների նախշերը պատկերավոր են, ոչ խորքերի իրական լուսանկարներ։ Թիկնոցը հիմնականում պինդ է․ մետաղական արտաքին միջուկը՝ հեղուկ։ Արտաքին պատյանը շատ բարակ է և հստակ ընտրելի է նաև իր անվան կոճակով։</p><p>Ջերմաստիճանը PREM-ի տվյալ չէ։ Գրաֆիկը տարբեր աղբյուրների գնահատումների ուսուցողական միջարկում է, ոչ ճշգրիտ գլոբալ ջերմային մոդել։ Մակերևույթի 15 °C-ը պայմանական մեկնարկ է, ոչ տեղային չափում։ Գրաֆիկին սեղմելով կամ խորության սահիչով կարող ես համեմատել արժեքները։</p><nav aria-label="Գիտական աղբյուրներ"><a v-for="source in earthSources" :key="source.url" :href="source.url" target="_blank" rel="noopener noreferrer">{{ source.name }} ↗</a></nav></div>
  </section>
</template>
